public class IncidentResponseService {
    private final SeasonPlanRepository plans;
    private final ExecutionPorts.Incidents incidents;
    private final ExecutionPorts.Corrections actions;
    private final ExecutionPorts.IncidentRules rules;
    private final CommandTransaction transactions;
    private final NotificationOutbox outbox;
    private final AuditLogService audit;
    private final Clock clock;
    
    public IncidentResponseService(SeasonPlanRepository plans, ExecutionPorts.Incidents incidents, ExecutionPorts.Corrections actions, ExecutionPorts.IncidentRules rules, CommandTransaction transactions, NotificationOutbox outbox, AuditLogService audit, Clock clock) {
        this.plans = plans;
        this.incidents = incidents;
        this.actions = actions;
        this.rules = rules;
        this.transactions = transactions;
        this.outbox = outbox;
        this.audit = audit;
        this.clock = clock;
    }
    
    public boolean hasCriticalCondition(UUID planId) {
        return incidents.forPlan(planId).stream().anyMatch(MagicIncident::critical);
    }
    
    public MagicIncident registerIncident(UUID planId, MagicIncident.Type type, String cause, String consequences, ActorRole role, String actorId) {
        requireResponder(role);
        return transactions.execute(planId, ()->{
            mutablePlan(planId);
            MagicIncident incident = new MagicIncident(UUID.randomUUID(), planId, type, rules.severityFor(type), MagicIncident.Status.OPEN, cause, consequences, actorId, clock.instant());
            incidents.save(incident);
            audit.append(planId, AuditAction.MAGIC_INCIDENT_REGISTERED, actorId, incident.id().toString());
            notifyIncident(incident, "registered");
            return incident;
        });
    }
    
    public MagicIncident overrideSeverity(UUID id, MagicIncident.Severity severity, String reason, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.CHIEF_GUARDIAN);
        if (reason == null || reason.isBlank()) UseCaseSupport.reject("reason", "severity override requires a reason");
        return transactions.execute(incident(id).seasonPlanId(), ()->{
            MagicIncident current = incident(id);
            mutablePlan(current.seasonPlanId());
            MagicIncident changed = current.withSeverity(severity);
            incidents.save(changed);
            audit.append(current.seasonPlanId(), AuditAction.INCIDENT_SEVERITY_CHANGED, actorId, reason);
            notifyIncident(changed, "severity:" + severity);
            return changed;
        });
    }
    
    public CorrectionAction createAction(UUID planId, UUID incidentId, String description, String owner, Instant deadline, ActorRole role, String actorId) {
        requireResponder(role);
        return transactions.execute(planId, ()->{
            mutablePlan(planId);
            if (incidentId != null && !incident(incidentId).seasonPlanId().equals(planId)) UseCaseSupport.reject("incident", "incident belongs to another plan");
            UUID id = UUID.randomUUID();
            CorrectionAction action = CorrectionAction.open(id, planId, incidentId, "manual:" + id, description, owner, deadline);
            actions.save(action);
            audit.append(planId, AuditAction.CORRECTION_ACTION_CREATED, actorId, id.toString());
            outbox.enqueue(new NotificationOutbox.Event("correction:" + action.id(), planId, "CORRECTION_ASSIGNED", Set.of(owner), Set.of(NotificationOutbox.Channel.IN_APP, NotificationOutbox.Channel.EMAIL), description, clock.instant()));
            return action;
        });
    }
    
    public CorrectionAction changeAction(UUID id, CorrectionAction.Status status, String reason, ActorRole role, String actorId) {
        ValidationSupport.requireAnyRole(role, ActorRole.CHIEF_GUARDIAN, ActorRole.MAGIC_ANOMALY_CONTROLLER, ActorRole.CLIMATE_BALANCER, ActorRole.TALENT_COORDINATOR, ActorRole.FAIRY_PARTICIPANT);
        return transactions.execute(action(id).seasonPlanId(), ()->{
            CorrectionAction current = action(id);
            mutablePlan(current.seasonPlanId());
            if ((role == ActorRole.FAIRY_PARTICIPANT || role == ActorRole.TALENT_COORDINATOR) && !current.owner().equals(actorId)) {
                throw new AccessDeniedForRoleException(role);
            }
            CorrectionAction changed = current.transition(status, reason);
            actions.save(changed);
            audit.append(current.seasonPlanId(), AuditAction.CORRECTION_ACTION_CHANGED, actorId, status.name());
            return changed;
        });
    }
    
    public MagicIncident resolveIncident(UUID id, ActorRole role, String actorId) {
        requireResponder(role);
        return transactions.execute(incident(id).seasonPlanId(), ()->{
            MagicIncident current = incident(id);
            mutablePlan(current.seasonPlanId());
            if (actions.forPlan(current.seasonPlanId()).stream().anyMatch((action)->id.equals(action.incidentId()) && !action.terminal())) {
                UseCaseSupport.reject("correctionActions", "linked correction actions are incomplete");
            }
            MagicIncident resolved = current.resolve();
            incidents.save(resolved);
            audit.append(current.seasonPlanId(), AuditAction.MAGIC_INCIDENT_RESOLVED, actorId, id.toString());
            return resolved;
        });
    }
    
    public MagicIncident reopenIncident(UUID id, ActorRole role, String actorId) {
        requireResponder(role);
        return transactions.execute(incident(id).seasonPlanId(), ()->{
            MagicIncident current = incident(id);
            mutablePlan(current.seasonPlanId());
            MagicIncident reopened = current.reopen();
            incidents.save(reopened);
            audit.append(current.seasonPlanId(), AuditAction.MAGIC_INCIDENT_REOPENED, actorId, id.toString());
            notifyIncident(reopened, "reopened");
            return reopened;
        });
    }
    
    public void escalateOverdue() {
        for (CorrectionAction candidate : actions.allOpen()) {
            transactions.execute(candidate.seasonPlanId(), ()->{
                CorrectionAction current = action(candidate.id());
                if (current.overdue(clock.instant())) {
                    long level = Duration.between(current.deadline(), clock.instant()).toDays() + 1;
                    outbox.enqueue(new NotificationOutbox.Event("overdue:" + current.id() + ":" + level + ":" + current.deadline(), current.seasonPlanId(), "CORRECTION_OVERDUE", Set.copyOf(java.util.List.of("CHIEF_GUARDIAN", "MAGIC_ANOMALY_CONTROLLER", current.owner())), Set.of(NotificationOutbox.Channel.IN_APP, NotificationOutbox.Channel.EMAIL), "\u041f\u0440\u043e\u0441\u0440\u043e\u0447\u0435\u043d\u043e: " + current.description(), clock.instant()));
                }
                return null;
            });
        }
    }
    
    private void notifyIncident(MagicIncident incident, String event) {
        outbox.enqueue(new NotificationOutbox.Event("incident:" + incident.id() + ":" + event + ":" + UUID.randomUUID(), incident.seasonPlanId(), "INCIDENT_REGISTERED", Set.of("CHIEF_GUARDIAN", "MAGIC_ANOMALY_CONTROLLER"), Set.of(NotificationOutbox.Channel.IN_APP, NotificationOutbox.Channel.EMAIL), incident.cause(), clock.instant()));
    }
    
    private void mutablePlan(UUID id) {
        UseCaseSupport.plan(plans, id, SeasonPlanStatus.RITUAL_READY, SeasonPlanStatus.ACTIVE);
    }
    
    private MagicIncident incident(UUID id) {
        return incidents.find(id).orElseThrow(()->new NotFoundException("incident not found: " + id));
    }
    
    private CorrectionAction action(UUID id) {
        return actions.find(id).orElseThrow(()->new NotFoundException("correction action not found: " + id));
    }
    
    private void requireResponder(ActorRole role) {
        ValidationSupport.requireAnyRole(role, ActorRole.CHIEF_GUARDIAN, ActorRole.MAGIC_ANOMALY_CONTROLLER, ActorRole.CLIMATE_BALANCER);
    }
}

public class MonitoringService {
    
    public class Measurement {
        private final String source;
        private final String eventId;
        private final String metric;
        private final String unit;
        private final BigDecimal value;
        private final Instant observedAt;
    }
    private final SeasonPlanRepository plans;
    private final ExecutionPorts.Metrics metrics;
    private final ExecutionPorts.Incidents incidents;
    private final ExecutionPorts.Corrections actions;
    private final ExecutionPorts.MetricRules rules;
    private final NotificationOutbox outbox;
    private final CommandTransaction transactions;
    private final AuditLogService audit;
    private final Clock clock;
    
    public MonitoringService(SeasonPlanRepository plans, ExecutionPorts.Metrics metrics, ExecutionPorts.Incidents incidents, ExecutionPorts.Corrections actions, ExecutionPorts.MetricRules rules, NotificationOutbox outbox, CommandTransaction transactions, AuditLogService audit, Clock clock) {
        this.plans = plans;
        this.metrics = metrics;
        this.incidents = incidents;
        this.actions = actions;
        this.rules = rules;
        this.outbox = outbox;
        this.transactions = transactions;
        this.audit = audit;
        this.clock = clock;
    }
    
    public ClimateMetric record(UUID planId, Measurement input, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.CLIMATE_BALANCER);
        return transactions.execute(planId, ()->recordInsideCommand(planId, input, actorId));
    }
    
    public List<ClimateMetric> importMetrics(UUID planId, List<Measurement> inputs, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.CLIMATE_BALANCER);
        return transactions.execute(planId, ()->inputs.stream().map((input)->recordInsideCommand(planId, input, actorId)).toList());
    }
    
    public List<ClimateMetric> history(UUID planId) {
        UseCaseSupport.plan(plans, planId);
        return metrics.forPlan(planId).stream().sorted(java.util.Comparator.comparing(ClimateMetric::observedAt).thenComparing(ClimateMetric::id)).toList();
    }
    
    private ClimateMetric recordInsideCommand(UUID planId, Measurement input, String actorId) {
        UseCaseSupport.plan(plans, planId, SeasonPlanStatus.ACTIVE);
        MetricDefinition definition = MetricDefinition.forKey(input.metric());
        if (!definition.unit().equals(input.unit())) throw new IllegalArgumentException("unit does not match metric catalog");
        /*missing*/ existing = metrics.byImportKey(input.source(), input.eventId());
        if (existing.isPresent()) {
            ClimateMetric old = existing.get();
            if (!old.seasonPlanId().equals(planId) || old.definition() != definition || old.value().compareTo(input.value()) != 0 || !old.observedAt().equals(input.observedAt())) throw new IllegalArgumentException("import key reused for different measurement");
            return old;
        }
        /*missing*/ rule = rules.forMetric(planId, definition);
        ClimateMetric metric = new ClimateMetric(UUID.randomUUID(), planId, input.source(), input.eventId(), definition, input.value(), rule.target(), rule.tolerance(), null, input.observedAt());
        UUID incidentId = null;
        if (metric.critical()) {
            incidentId = UUID.randomUUID();
            incidents.save(new MagicIncident(incidentId, planId, MagicIncident.Type.CLIMATE, MagicIncident.Severity.CRITICAL, MagicIncident.Status.OPEN, "\u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 " + definition.key(), "deviation_score=" + metric.deviationScore(), actorId, clock.instant()));
            audit.append(planId, AuditAction.MAGIC_INCIDENT_REGISTERED, actorId, incidentId.toString());
            outbox.enqueue(new NotificationOutbox.Event("critical-metric:" + metric.id(), planId, "CRITICAL_METRIC", Set.copyOf(List.of("CHIEF_GUARDIAN", "MAGIC_ANOMALY_CONTROLLER", rule.owner())), Set.of(NotificationOutbox.Channel.IN_APP, NotificationOutbox.Channel.EMAIL), "\u041a\u0440\u0438\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435: " + metric.deviationScore(), clock.instant()));
        }
        if (metric.deviating()) {
            String key = planId + ":" + metric.id() + ":" + rule.version();
            if (actions.byKey(key).isEmpty()) {
                CorrectionAction action = CorrectionAction.open(UUID.randomUUID(), planId, incidentId, key, "\u0423\u0441\u0442\u0440\u0430\u043d\u0438\u0442\u044c \u043e\u0442\u043a\u043b\u043e\u043d\u0435\u043d\u0438\u0435 " + definition.key(), rule.owner(), clock.instant().plus(rule.responseTime()));
                actions.save(action);
                audit.append(planId, AuditAction.CORRECTION_ACTION_CREATED, actorId, action.id().toString());
                if (!metric.critical()) {
                    outbox.enqueue(new NotificationOutbox.Event("correction:" + action.id(), planId, "CORRECTION_ASSIGNED", Set.of(rule.owner()), Set.of(NotificationOutbox.Channel.IN_APP, NotificationOutbox.Channel.EMAIL), action.description(), clock.instant()));
                }
            }
        }
        metrics.save(metric);
        audit.append(planId, AuditAction.CLIMATE_METRIC_RECORDED, actorId, metric.id().toString());
        return metric;
    }
}

