public class RitualService {
    private final SeasonPlanRepository plans;
    private final ExecutionPorts.Rituals rituals;
    private final ExecutionPorts.Incidents incidents;
    private final ExecutionPorts.LaunchReadiness readiness;
    private final CommandTransaction transactions;
    private final AuditLogService audit;
    private final Clock clock;
    
    public RitualService(SeasonPlanRepository plans, ExecutionPorts.Rituals rituals, ExecutionPorts.Incidents incidents, ExecutionPorts.LaunchReadiness readiness, CommandTransaction transactions, AuditLogService audit, Clock clock) {
        this.plans = plans;
        this.rituals = rituals;
        this.incidents = incidents;
        this.readiness = readiness;
        this.transactions = transactions;
        this.audit = audit;
        this.clock = clock;
    }
    
    public RitualSession start(UUID planId, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.TALENT_COORDINATOR);
        return transactions.execute(planId, ()->{
            UseCaseSupport.plan(plans, planId, SeasonPlanStatus.RITUAL_READY);
            /*missing*/ previous = rituals.forPlan(planId);
            if (previous.stream().anyMatch((session)->session.inProgress() || session.result() == RitualSession.Result.SUCCESS)) {
                UseCaseSupport.reject("ritualSession", "an attempt is already running or successful");
            }
            /*missing*/ check = readiness.inspect(planId);
            if (!check.blockers().isEmpty() || incidents.forPlan(planId).stream().anyMatch(MagicIncident::critical)) {
                UseCaseSupport.reject("readiness", "ritual readiness failed: " + check.blockers());
            }
            int attempt = previous.stream().mapToInt(RitualSession::attempt).max().orElse(0) + 1;
            RitualSession session = RitualSession.start(UUID.randomUUID(), planId, attempt, actorId, clock.instant(), check.participants());
            rituals.save(session);
            audit.append(planId, AuditAction.RITUAL_SESSION_STARTED, actorId, session.id().toString());
            return session;
        });
    }
    
    public RitualSession recordEvent(UUID id, String type, String payload, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.TALENT_COORDINATOR);
        return transactions.execute(get(id).seasonPlanId(), ()->{
            RitualSession session = get(id);
            UseCaseSupport.plan(plans, session.seasonPlanId(), SeasonPlanStatus.RITUAL_READY);
            RitualSession updated = session.addEvent(new RitualSession.Event(clock.instant(), type, payload));
            rituals.save(updated);
            audit.append(session.seasonPlanId(), AuditAction.RITUAL_EVENT_RECORDED, actorId, type);
            return updated;
        });
    }
    
    public RitualSession finish(UUID id, String failureCode, String failureMessage, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.TALENT_COORDINATOR);
        if ((failureCode == null) != (failureMessage == null)) throw new IllegalArgumentException("failure code and message must be supplied together");
        return transactions.execute(get(id).seasonPlanId(), ()->{
            RitualSession session = get(id);
            SeasonPlan plan = UseCaseSupport.copy(UseCaseSupport.plan(plans, session.seasonPlanId(), SeasonPlanStatus.RITUAL_READY));
            /*missing*/ check = readiness.inspect(plan.id());
            String code = failureCode;
            String message = failureMessage;
            if (code == null && (!check.blockers().isEmpty() || incidents.forPlan(plan.id()).stream().anyMatch(MagicIncident::critical) || !new java.util.HashSet<>(check.participants()).equals(new java.util.HashSet<>(session.participants())))) {
                code = "READINESS_BLOCKED";
                message = "\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u0433\u043e\u0442\u043e\u0432\u043d\u043e\u0441\u0442\u0438 \u043d\u0435 \u043f\u0440\u043e\u0439\u0434\u0435\u043d\u0430";
            }
            if (code == null && !session.events().stream().map(RitualSession.Event::type).toList().containsAll(check.requiredEvents())) {
                code = "MISSING_EVENTS";
                message = "\u041d\u0435 \u0437\u0430\u0432\u0435\u0440\u0448\u0435\u043d\u044b \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u0441\u043e\u0431\u044b\u0442\u0438\u044f \u0440\u0438\u0442\u0443\u0430\u043b\u0430";
            }
            RitualSession completed = code == null ? session.succeed(clock.instant()) : session.fail(code, message, clock.instant());
            if (completed.result() == RitualSession.Result.SUCCESS) plan.activate(completed, actorId, clock.instant());
            rituals.save(completed);
            audit.append(plan.id(), AuditAction.RITUAL_SESSION_FINISHED, actorId, completed.result().name());
            if (completed.result() == RitualSession.Result.SUCCESS) {
                plans.save(plan);
                audit.append(plan.id(), AuditAction.SEASON_PLAN_ACTIVATED, actorId, completed.id().toString());
            }
            return completed;
        });
    }
    
    private RitualSession get(UUID id) {
        return rituals.find(id).orElseThrow(()->new NotFoundException("ritual session not found: " + id));
    }
}

public class PlanningService {
    private final SeasonPlanRepository plans;
    private final AuditLogService audit;
    private final NaturalCalendarService calendar;
    private final CommandTransaction transactions;
    private final Clock clock;
    
    public PlanningService(SeasonPlanRepository plans, AuditLogService audit, NaturalCalendarService calendar, CommandTransaction transactions, Clock clock) {
        this.plans = plans;
        this.audit = audit;
        this.calendar = calendar;
        this.transactions = transactions;
        this.clock = clock;
    }
    
    public SeasonPlan createDraft(SeasonPlan draft, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.FAIRY_PLANNER);
        validatePlan(draft);
        SeasonPlan created = SeasonPlan.createDraft(UUID.randomUUID(), draft.seasonType(), draft.targetTerritories(), draft.timeWindows(), draft.naturalPhenomenonParameters(), draft.targetClimateMetrics(), List.of(new ChecklistItem("calendar-reviewed", false), new ChecklistItem("roles-reviewed", false)), actorId, clock.instant());
        plans.save(created);
        audit.append(created.id(), AuditAction.SEASON_PLAN_CREATED, actorId, null);
        return created;
    }
    
    public SeasonPlan updateDraft(UUID id, SeasonPlan draft, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.FAIRY_PLANNER);
        return transactions.execute(id, ()->{
            SeasonPlan existing = get(id);
            validatePlan(draft);
            existing.updateDraftFieldsFrom(draft, actorId, clock.instant());
            audit.append(id, AuditAction.SEASON_PLAN_UPDATED, actorId, null);
            return plans.save(existing);
        });
    }
    
    public LinkedHashMap<String, List<String>> validatePlan(SeasonPlan plan) {
        LinkedHashMap<String, List<String>> errors = new LinkedHashMap<>();
        if (plan.seasonType() == null || plan.seasonType().isBlank()) {
            ValidationSupport.add(errors, "seasonType", "season type is required");
        }
        if (plan.timeWindows().isEmpty()) {
            ValidationSupport.add(errors, "timeWindows", "at least one time window is required");
        }
        if (plan.targetTerritories().isEmpty()) {
            ValidationSupport.add(errors, "targetTerritories", "at least one target territory is required");
        }
        if (plan.naturalPhenomenonParameters().isEmpty()) {
            ValidationSupport.add(errors, "naturalPhenomenonParameters", "natural phenomenon parameters are required");
        }
        if (plan.targetClimateMetrics().isEmpty()) {
            ValidationSupport.add(errors, "targetClimateMetrics", "target climate metrics are required");
        }
        for (TimeWindow window : plan.timeWindows()) {
            if (window.start() == null || window.end() == null || !window.start().isBefore(window.end())) {
                ValidationSupport.add(errors, "timeWindows", "each time window must have start before end");
                break;
            }
        }
        List<TimeWindow> sorted = plan.timeWindows().stream().filter((window)->window.start() != null && window.end() != null).sorted(Comparator.comparing(TimeWindow::start)).toList();
        for (int index = 1; index < sorted.size(); index++) {
            if (sorted.get(index - 1).overlaps(sorted.get(index))) {
                ValidationSupport.add(errors, "timeWindows", "time windows must not overlap");
                break;
            }
        }
        for (String error : calendar.validate(plan)) {
            ValidationSupport.add(errors, "naturalCalendar", error);
        }
        ValidationSupport.throwIfAny(errors);
        return errors;
    }
    
    public void validateForReview(SeasonPlan plan) {
        validatePlan(plan);
        /*missing*/ applicable = java.util.EnumSet.of(SeasonPlanStatus.SUBMITTED, SeasonPlanStatus.VERIFIED, SeasonPlanStatus.APPROVED, SeasonPlanStatus.RITUAL_READY, SeasonPlanStatus.ACTIVE);
        /*missing*/ errors = new LinkedHashMap<String, List<String>>();
        for (SeasonPlan other : plans.findAll()) {
            if (plan.id().equals(other.id()) || !applicable.contains(other.status())) continue;
            for (String territory : plan.targetTerritories()) {
                if (territory == null) continue;
                String normalized = territory.trim().toLowerCase(java.util.Locale.ROOT);
                boolean shared = other.targetTerritories().stream().filter(java.util.Objects::nonNull).anyMatch((value)->value.trim().toLowerCase(java.util.Locale.ROOT).equals(normalized));
                if (!shared) continue;
                for (TimeWindow window : plan.timeWindows()) {
                    for (TimeWindow otherWindow : other.timeWindows()) {
                        if (window.overlaps(otherWindow)) {
                            ValidationSupport.add(errors, "targetTerritories", "territory " + normalized + " conflicts with plan " + other.id() + " window " + otherWindow);
                        }
                    }
                }
            }
        }
        ValidationSupport.throwIfAny(errors);
    }
    
    public SeasonPlan submitForApproval(UUID id, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.FAIRY_PLANNER);
        return transactions.execute(id, ()->{
            SeasonPlan plan = get(id);
            validatePlan(plan);
            plan.submit(actorId, clock.instant());
            audit.append(id, AuditAction.SEASON_PLAN_SUBMITTED, actorId, null);
            return plans.save(plan);
        });
    }
    
    public SeasonPlan get(UUID id) {
        return plans.findById(id).orElseThrow(()->new NotFoundException("season plan not found: " + id));
    }
    
    public List<SeasonPlan> listPlans() {
        return plans.findAll();
    }
}

public class PollenService {
    private final SeasonPlanRepository plans;
    private final PollenTreeClient client;
    private final Supplier<NotificationOutbox> outbox;
    private final CommandTransaction transactions;
    private final AuditLogService audit;
    private final Clock clock;
    
    public PollenService(SeasonPlanRepository plans, PollenTreeClient client, Supplier<NotificationOutbox> outbox, CommandTransaction transactions, AuditLogService audit, Clock clock) {
        this.plans = plans;
        this.client = client;
        this.outbox = outbox;
        this.transactions = transactions;
        this.audit = audit;
        this.clock = clock;
    }
    
    public PollenReservation requestReservation(UUID planId, int requestedAmount, ActorRole role, String actorId) {
        return requestReservation(planId, UUID.randomUUID(), requestedAmount, role, actorId);
    }
    
    public PollenReservation requestReservation(UUID planId, UUID requestId, int requestedAmount, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.POLLEN_GUARDIAN);
        UseCaseSupport.plan(plans, planId);
        requirePositive(requestedAmount, "requestedAmount");
        return client.requestReservation(planId, requestId, requestedAmount, actorId);
    }
    
    public PollenReservation confirmReservation(UUID id, int confirmedAmount, String comment, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.POLLEN_GUARDIAN);
        requirePositive(confirmedAmount, "confirmedAmount");
        PollenReservation result = client.confirmReservation(id, confirmedAmount, comment, actorId);
        return auditDecision(result, AuditAction.POLLEN_RESERVATION_CONFIRMED, actorId, comment);
    }
    
    public PollenReservation rejectReservation(UUID id, String comment, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.POLLEN_GUARDIAN);
        PollenReservation result = client.rejectReservation(id, comment, actorId);
        return auditDecision(result, AuditAction.POLLEN_RESERVATION_REJECTED, actorId, comment);
    }
    
    public PollenReservation get(UUID id) {
        return client.findById(id).orElseThrow(()->new NotFoundException("pollen reservation not found: " + id));
    }
    
    public Optional<PollenReservation> findLatestBySeasonPlanId(UUID planId) {
        return client.findLatestBySeasonPlanId(planId);
    }
    
    public Optional<PollenReservation> findAuthoritativeConfirmedBySeasonPlanId(UUID planId) {
        return client.findAuthoritativeConfirmedBySeasonPlanId(planId);
    }
    
    public Optional<PollenUsage> usage(UUID planId) {
        return client.summary(planId).map(PollenTreeClient.Summary::snapshot);
    }
    
    public PollenCapacity capacity() {
        return client.capacity();
    }
    
    public PollenUsage recordConsumption(UUID planId, UUID clientEventId, BigDecimal grams, ActorRole role, String actorId) {
        ValidationSupport.requireRole(role, ActorRole.POLLEN_GUARDIAN);
        Objects.requireNonNull(clientEventId);
        BigDecimal amount = Objects.requireNonNull(grams).setScale(3, RoundingMode.HALF_UP);
        if (amount.signum() <= 0) throw new IllegalArgumentException("consumption grams must be positive after rounding");
        NotificationOutbox notifications = outbox.get();
        return transactions.execute(planId, ()->{
            UseCaseSupport.plan(plans, planId, SeasonPlanStatus.ACTIVE);
            PollenTreeClient.Summary summary = client.recordConsumption(planId, clientEventId, amount);
            if (summary.actualGrams().compareTo(summary.confirmedGrams().multiply(new BigDecimal("0.8"))) >= 0) notify(notifications, planId, clientEventId, summary, "80", false);
            if (summary.actualGrams().compareTo(summary.confirmedGrams()) >= 0) notify(notifications, planId, clientEventId, summary, "100", false);
            if (summary.actualGrams().compareTo(summary.confirmedGrams()) > 0) notify(notifications, planId, clientEventId, summary, "OVER_100", true);
            audit.appendOnce(eventId("pollen-consumption:" + planId + ":" + clientEventId), planId, AuditAction.POLLEN_CONSUMPTION_RECORDED, actorId, clientEventId.toString());
            return summary.snapshot();
        });
    }
    
    private PollenReservation auditDecision(PollenReservation result, AuditAction action, String actorId, String comment) {
        String auditComment = "reservationId=" + result.id() + "; " + Objects.toString(comment, "");
        audit.appendOnce(eventId("pollen-decision:" + result.id() + ":" + action.name()), result.seasonPlanId(), action, actorId, auditComment);
        return result;
    }
    
    private UUID eventId(String key) {
        return UUID.nameUUIDFromBytes(key.getBytes(StandardCharsets.UTF_8));
    }
    
    private void requirePositive(int amount, String field) {
        if (amount <= 0) throw new DomainValidationException(Map.of(field, List.of("amount must be positive")));
    }
    
    private void notify(NotificationOutbox notifications, UUID planId, UUID eventId, PollenTreeClient.Summary summary, String threshold, boolean chief) {
        notifications.enqueue(new NotificationOutbox.Event("pollen:" + summary.reservationId() + ":" + threshold + ":" + eventId, planId, "POLLEN_" + threshold, chief ? Set.of("POLLEN_GUARDIAN", "TALENT_COORDINATOR", "CHIEF_GUARDIAN") : Set.of("POLLEN_GUARDIAN", "TALENT_COORDINATOR"), Set.of(NotificationOutbox.Channel.IN_APP, NotificationOutbox.Channel.EMAIL), "\u0420\u0430\u0441\u0445\u043e\u0434 \u043f\u044b\u043b\u044c\u0446\u044b: " + summary.actualGrams() + " / " + summary.confirmedGrams() + " g", clock.instant()));
    }
}

