public final class ValidationSupport {
    
    private ValidationSupport() {
    }
    
    public static void requireRole(ActorRole actual, ActorRole expected) {
        if (actual != expected) {
            throw new AccessDeniedForRoleException(actual);
        }
    }
    
    public static void requireAnyRole(ActorRole actual, ActorRole... allowed) {
        for (ActorRole role : allowed) {
            if (actual == role) {
                return;
            }
        }
        throw new AccessDeniedForRoleException(actual);
    }
    
    public static void add(Map<String, List<String>> errors, String field, String message) {
        errors.computeIfAbsent(field, (ignored)->new ArrayList<>()).add(message);
    }
    
    public static void throwIfAny(LinkedHashMap<String, List<String>> errors) {
        if (!errors.isEmpty()) {
            throw new DomainValidationException(errors);
        }
    }
}

public final class UseCaseSupport {
    
    private UseCaseSupport() {
    }
    
    public static SeasonPlan plan(SeasonPlanRepository plans, UUID id, SeasonPlanStatus... allowed) {
        SeasonPlan plan = plans.findById(id).orElseThrow(()->new NotFoundException("season plan not found: " + id));
        if (allowed.length > 0 && Arrays.stream(allowed).noneMatch((status)->status == plan.status())) {
            reject("status", "operation is not allowed in " + plan.status());
        }
        return plan;
    }
    
    public static void reject(String field, String message) {
        LinkedHashMap<String, List<String>> errors = new LinkedHashMap<>();
        errors.put(field, List.of(message));
        throw new DomainValidationException(errors);
    }
    
    public static SeasonPlan copy(SeasonPlan plan) {
        return SeasonPlan.rehydrate(plan.id(), plan.seasonType(), plan.targetTerritories(), plan.timeWindows(), plan.naturalPhenomenonParameters(), plan.targetClimateMetrics(), plan.status(), plan.approvalComment(), plan.readinessChecklist(), plan.createdBy(), plan.updatedBy(), plan.createdAt(), plan.updatedAt(), plan.approvalConditions());
    }
}

