        private final Duration readTimeout;
        @DefaultValue("1000")
        private final BigDecimal fakeCapacityGrams;
        
        public Settings(@DefaultValue("rest")
        String mode, String baseUrl, String apiKey, @DefaultValue("2s")
        Duration connectTimeout, @DefaultValue("3s")
        Duration readTimeout, @DefaultValue("1000")
        BigDecimal fakeCapacityGrams) {
            if (!"rest".equals(mode) && !"fake".equals(mode)) {
                throw new IllegalArgumentException("Pollen Tree mode must be rest or fake");
            }
            bounded(connectTimeout);
            bounded(readTimeout);
            if (fakeCapacityGrams == null || fakeCapacityGrams.signum() < 0) {
