public class PollenUsage {
    private final UUID reservationId;
    private final BigDecimal confirmedGrams;
    private final BigDecimal actualGrams;
    private final String sourceVersion;
    
    public PollenUsage(UUID reservationId, BigDecimal confirmedGrams, BigDecimal actualGrams, String sourceVersion) {
        Objects.requireNonNull(reservationId);
        Objects.requireNonNull(confirmedGrams);
        Objects.requireNonNull(actualGrams);
        if (confirmedGrams.signum() <= 0 || actualGrams.signum() < 0 || sourceVersion == null || sourceVersion.isBlank()) {
            throw new IllegalArgumentException("valid authoritative pollen totals are required");
        }
        confirmedGrams = confirmedGrams.setScale(3, RoundingMode.HALF_UP);
        actualGrams = actualGrams.setScale(3, RoundingMode.HALF_UP);
        if (confirmedGrams.signum() <= 0) throw new IllegalArgumentException("confirmed grams round to zero");
    }
    
    public BigDecimal variance() {
        return actualGrams.subtract(confirmedGrams);
    }
    
    public BigDecimal consumptionRatio() {
        return actualGrams.divide(confirmedGrams, 4, RoundingMode.HALF_UP);
    }
}

public class RitualSession {
    private final UUID id;
    private final UUID seasonPlanId;
    private final int attempt;
    private final String starter;
    private final Instant startedAt;
    private final Instant completedAt;
    private final List<Participant> participants;
    private final List<Event> events;
    private final Result result;
    private final String failureCode;
    private final String failureMessage;
    
    public enum Result {
        /*public static final*/ SUCCESS /* = new Result() */ /*enum*/ ,
        /*public static final*/ FAILED /* = new Result() */ /*enum*/ ;
    }
    
    public class Participant {
        private final String fairyId;
        private final String role;
        private final Instant confirmedAt;
        
        public Participant(String fairyId, String role, Instant confirmedAt) {
            requireText(fairyId);
            requireText(role);
            Objects.requireNonNull(confirmedAt);
        }
    }
    
    public class Event {
        private final Instant occurredAt;
        private final String type;
        private final String payload;
        
        public Event(Instant occurredAt, String type, String payload) {
            Objects.requireNonNull(occurredAt);
            requireText(type);
            Objects.requireNonNull(payload);
        }
    }
    
    public RitualSession(UUID id, UUID seasonPlanId, int attempt, String starter, Instant startedAt, Instant completedAt, List<Participant> participants, List<Event> events, Result result, String failureCode, String failureMessage) {
        Objects.requireNonNull(id);
        Objects.requireNonNull(seasonPlanId);
        Objects.requireNonNull(startedAt);
        requireText(starter);
        if (attempt < 1) throw new IllegalArgumentException("attempt must be positive");
        participants = List.copyOf(participants);
        events = List.copyOf(events);
        if (participants.isEmpty()) throw new IllegalArgumentException("participants are required");
        if ((result == null) != (completedAt == null)) throw new IllegalArgumentException("result requires completion time");
        if (completedAt != null && (completedAt.isBefore(startedAt) || (!events.isEmpty() && completedAt.isBefore(events.get(events.size() - 1).occurredAt())))) {
            throw new IllegalArgumentException("completion precedes ritual events");
        }
        if (result == Result.FAILED) {
            requireText(failureCode);
            requireText(failureMessage);
        } else if (failureCode != null || failureMessage != null) throw new IllegalArgumentException("only failed sessions have failure details");
    }
    
    public static RitualSession start(UUID id, UUID planId, int attempt, String actor, Instant now, List<Participant> participants) {
        return new RitualSession(id, planId, attempt, actor, now, null, participants, List.of(), null, null, null);
    }
    
    public boolean inProgress() {
        return result == null;
    }
    
    public RitualSession addEvent(Event event) {
        requireInProgress();
        Instant previous = events.isEmpty() ? startedAt : events.get(events.size() - 1).occurredAt();
        if (event.occurredAt().isBefore(previous)) throw new IllegalArgumentException("ritual events must be ordered");
        List<Event> updated = new ArrayList<>(events);
        updated.add(event);
        return new RitualSession(id, seasonPlanId, attempt, starter, startedAt, null, participants, updated, null, null, null);
    }
    
    public RitualSession succeed(Instant now) {
        return finish(Result.SUCCESS, null, null, now);
    }
    
    public RitualSession fail(String code, String message, Instant now) {
        return finish(Result.FAILED, code, message, now);
    }
    
    private RitualSession finish(Result result, String code, String message, Instant now) {
        requireInProgress();
        return new RitualSession(id, seasonPlanId, attempt, starter, startedAt, now, participants, events, result, code, message);
    }
    
    private void requireInProgress() {
        if (!inProgress()) throw new IllegalArgumentException("completed ritual is immutable");
    }
    
    private static void requireText(String value) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException("non-blank value required");
    }
}

