public class Snapshot {
    private final String seasonType;
    private final String catalogVersion;
    private final List<String> territories;
    private final Map<String, String> phenomena;
    private final Map<String, Double> targets;
    private final List<TaskResult> tasks;
    private final List<ClimateMetric> metrics;
    private final List<MagicIncident> incidents;
    private final List<CorrectionAction> actions;
    private final List<RitualSession> rituals;
    private final PollenUsage pollen;
    
    public Snapshot(String seasonType, String catalogVersion, List<String> territories, Map<String, String> phenomena, Map<String, Double> targets, List<TaskResult> tasks, List<ClimateMetric> metrics, List<MagicIncident> incidents, List<CorrectionAction> actions, List<RitualSession> rituals, PollenUsage pollen) {
        Objects.requireNonNull(seasonType);
        if (catalogVersion == null || catalogVersion.isBlank()) throw new IllegalArgumentException("catalog version required");
        territories = List.copyOf(territories);
        phenomena = Map.copyOf(phenomena);
        targets = Map.copyOf(targets);
        tasks = List.copyOf(tasks);
        metrics = List.copyOf(metrics);
        incidents = List.copyOf(incidents);
        actions = List.copyOf(actions);
        rituals = List.copyOf(rituals);
    }
    
    public List<String> blockers() {
        java.util.ArrayList<String> failures = new java.util.ArrayList<>();
        if (rituals.stream().noneMatch((r)->r.result() == RitualSession.Result.SUCCESS) || rituals.stream().anyMatch(RitualSession::inProgress)) failures.add("ritual-success");
        if (tasks.isEmpty() || tasks.stream().anyMatch((t)->!t.completed())) failures.add("completed-tasks");
        if (actions.stream().anyMatch((a)->!a.terminal())) failures.add("completed-corrections");
        if (incidents.stream().anyMatch(MagicIncident::critical)) failures.add("critical-incidents");
        if (targets.isEmpty() || !metrics.stream().map((m)->m.definition().key()).toList().containsAll(targets.keySet())) failures.add("climate-metrics");
        if (pollen == null) failures.add("pollen-totals");
        return List.copyOf(failures);
    }
    
    public Kpis kpis() {
        Map<MagicIncident.Severity, Long> counts = new EnumMap<>(MagicIncident.Severity.class);
        for (/*missing*/ severity : MagicIncident.Severity.values()) counts.put(severity, incidents.stream().filter((i)->i.severity() == severity).count());
        BigDecimal mean = metrics.isEmpty() ? null : metrics.stream().map(ClimateMetric::deviationScore).reduce(BigDecimal.ZERO, BigDecimal::add).divide(BigDecimal.valueOf(metrics.size()), 4, RoundingMode.HALF_UP);
        long completed = rituals.stream().filter((r)->!r.inProgress()).count();
        long successful = rituals.stream().filter((r)->r.result() == RitualSession.Result.SUCCESS).count();
        return new Kpis(pollen == null ? null : pollen.variance(), pollen == null ? null : pollen.consumptionRatio(), counts, mean, metrics.stream().filter(ClimateMetric::critical).count(), completed == 0 ? null : BigDecimal.valueOf(successful).divide(BigDecimal.valueOf(completed), 4, RoundingMode.HALF_UP));
    }
}

public class TimeWindow {
    private final LocalDateTime start;
    private final LocalDateTime end;
    
    public boolean overlaps(TimeWindow other) {
        return start != null && end != null && other.start != null && other.end != null && start.isBefore(other.end) && other.start.isBefore(end);
    }
}

public class ConfiguredNotificationRecipientResolver implements NotificationRecipientResolver {
    private final Map<String, String> recipients;
    
    public ConfiguredNotificationRecipientResolver(Map<String, String> recipients) {
        this.recipients = Map.copyOf(recipients);
    }
    
    @Override
    public String emailAddress(String recipientId) {
        String value = recipients.get(recipientId);
        try {
            if (value == null || value.isBlank() || value.contains("\r") || value.contains("\n")) throw new AddressException();
            InternetAddress address = new InternetAddress(value, true);
            address.validate();
            if (address.getPersonal() != null || !value.equals(address.getAddress())) throw new AddressException();
            return value;
        } catch (AddressException error) {
            throw new IllegalStateException("notification email address is not configured or invalid");
        }
    }
}

