    public JdbcNotificationDeliveryGateway(JdbcTemplate jdbc, SmtpNotificationEmailGateway email) {
        this.jdbc = jdbc;
        this.email = email;
    }
    
    @Override
    public void deliver(NotificationOutbox.Event event, String recipient, NotificationOutbox.Channel channel) {
        if (channel == NotificationOutbox.Channel.EMAIL) {
            email.send(event, recipient);
            return;
        }
        jdbc.update("insert into notification_inbox (event_id, recipient, season_plan_id, event_type, message, occurred_at)\nvalues (?, ?, ?, ?, ?, ?) on conflict (event_id, recipient) do nothing\n", event.deduplicationKey(), recipient, event.seasonPlanId(), event.type(), event.message(), Timestamp.from(event.occurredAt()));
    }
}

public class JdbcNotificationDeliveryWorker {
    private final JdbcTemplate jdbc;
    private final ObjectMapper mapper;
    private final NotificationDeliveryGateway gateway;
    private final TransactionTemplate transaction;
    private final Clock clock;
    
    public JdbcNotificationDeliveryWorker(JdbcTemplate jdbc, ObjectMapper mapper, NotificationDeliveryGateway gateway, PlatformTransactionManager manager, Clock clock) {
        this.jdbc = jdbc;
        this.mapper = mapper;
        this.gateway = gateway;
        this.transaction = new TransactionTemplate(manager);
        this.clock = clock;
    }
    
    @Scheduled(fixedDelayString = "${notifications.poll-delay-ms:30000}", initialDelayString = "${notifications.initial-delay-ms:60000}")
    public void deliverPending() {
        for (int i = 0; i < 100; i++) {
            Boolean processed = transaction.execute((status)->deliverOne());
            if (!Boolean.TRUE.equals(processed)) break;
        }
    }
    
    private boolean deliverOne() {
        Instant now = clock.instant();
        jdbc.update("update notification_outbox_deliveries set status = 'EXPIRED' where status = 'PENDING' and expires_at <= ?", Timestamp.from(now));
        List<Delivery> rows = jdbc.query("select d.event_id, d.recipient, d.channel, d.attempts, d.expires_at,\n       o.season_plan_id, o.event_type, o.recipients, o.channels, o.message, o.occurred_at\n  from notification_outbox_deliveries d join notification_outbox o on o.event_id = d.event_id\n where d.status = 'PENDING' and d.next_attempt_at <= ? and d.expires_at > ?\n order by d.next_attempt_at, d.event_id, d.recipient, d.channel\n for update of d skip locked limit 1\n", (rs,row)->new Delivery(rs.getString("event_id"), rs.getString("recipient"), NotificationOutbox.Channel.valueOf(rs.getString("channel")), rs.getInt("attempts"), rs.getTimestamp("expires_at").toInstant(), rs.getObject("season_plan_id", UUID.class), rs.getString("event_type"), rs.getString("recipients"), rs.getString("channels"), rs.getString("message"), rs.getTimestamp("occurred_at").toInstant()), Timestamp.from(now), Timestamp.from(now));
        if (rows.isEmpty()) return false;
        Delivery delivery = rows.get(0);
        try {
            gateway.deliver(event(delivery), delivery.recipient(), delivery.channel());
            jdbc.update("update notification_outbox_deliveries set status = 'DELIVERED', attempts = attempts + 1, delivered_at = ? where event_id = ? and recipient = ? and channel = ?", Timestamp.from(now), delivery.eventId(), delivery.recipient(), delivery.channel().name());
        } catch (RuntimeException failure) {
            long delaySeconds = 1L << Math.min(delivery.attempts(), 16);
            Instant next = now.plusSeconds(delaySeconds);
            if (next.isAfter(delivery.expiresAt())) next = delivery.expiresAt();
            jdbc.update("update notification_outbox_deliveries set attempts = attempts + 1, next_attempt_at = ? where event_id = ? and recipient = ? and channel = ?", Timestamp.from(next), delivery.eventId(), delivery.recipient(), delivery.channel().name());
        }
        return true;
    }
    
    private NotificationOutbox.Event event(Delivery delivery) {
        try {
            Set<String> recipients = mapper.readValue(delivery.recipients(), new TypeReference<>(){
            });
            Set<NotificationOutbox.Channel> channels = mapper.readValue(delivery.channels(), new TypeReference<>(){
            });
            return new NotificationOutbox.Event(delivery.eventId(), delivery.planId(), delivery.type(), recipients, channels, delivery.message(), delivery.occurredAt());
        } catch (com.fasterxml.jackson.core.JsonProcessingException error) {
            throw new IllegalStateException("invalid outbox payload", error);
        }
    }
    
    private class Delivery {
        private final String eventId;
        private final String recipient;
        private final NotificationOutbox.Channel channel;
        private final int attempts;
        private final Instant expiresAt;
        private final UUID planId;
        private final String type;
        private final String recipients;
        private final String channels;
        private final String message;
        private final Instant occurredAt;
    }
}

