@Repository
public class JdbcNotificationOutbox implements NotificationOutbox {
    private final JdbcTemplate jdbc;
    private final ObjectMapper mapper;
    
    public JdbcNotificationOutbox(JdbcTemplate jdbc, ObjectMapper mapper) {
        this.jdbc = jdbc;
        this.mapper = mapper;
    }
    
    @Override
    @Transactional(propagation = Propagation.MANDATORY)
    public void enqueue(Event event) {
        int inserted = jdbc.update("insert into notification_outbox\n    (event_id, season_plan_id, event_type, recipients, channels, message, occurred_at)\nvalues (?, ?, ?, cast(? as jsonb), cast(? as jsonb), ?, ?)\non conflict (event_id) do nothing\n", event.deduplicationKey(), event.seasonPlanId(), event.type(), JdbcJson.write(mapper, event.recipients()), JdbcJson.write(mapper, event.channels()), event.message(), Timestamp.from(event.occurredAt()));
        if (inserted == 0) return;
        for (String recipient : event.recipients()) {
            for (Channel channel : event.channels()) {
                jdbc.update("insert into notification_outbox_deliveries (event_id, recipient, channel, next_attempt_at, expires_at)\nvalues (?, ?, ?, ?, ?) on conflict do nothing\n", event.deduplicationKey(), recipient, channel.name(), Timestamp.from(event.occurredAt()), Timestamp.from(event.occurredAt().plusSeconds(24 * 60 * 60)));
            }
        }
    }
}

