    @Override
    @Transactional
    public SeasonPlan save(SeasonPlan plan) {
        int updated = jdbc.update("update season_plans\n   set season_type = ?,\n       status = ?,\n       approval_comment = ?,\n       approval_conditions = cast(? as jsonb),\n       natural_phenomenon_parameters = cast(? as jsonb),\n       target_climate_metrics = cast(? as jsonb),\n       updated_by = ?,\n       updated_at = ?\n where id = ?\n", plan.seasonType(), plan.status().name(), plan.approvalComment(), JdbcJson.write(objectMapper, plan.approvalConditions()), JdbcJson.write(objectMapper, plan.naturalPhenomenonParameters()), JdbcJson.write(objectMapper, plan.targetClimateMetrics()), plan.updatedBy(), Timestamp.from(plan.updatedAt()), plan.id());
        if (updated == 0) {
            jdbc.update("insert into season_plans (\n    id, season_type, status, approval_comment, approval_conditions, natural_phenomenon_parameters,\n    target_climate_metrics, created_by, updated_by, created_at, updated_at\n) values (?, ?, ?, ?, cast(? as jsonb), cast(? as jsonb), cast(? as jsonb), ?, ?, ?, ?)\n", plan.id(), plan.seasonType(), plan.status().name(), plan.approvalComment(), JdbcJson.write(objectMapper, plan.approvalConditions()), JdbcJson.write(objectMapper, plan.naturalPhenomenonParameters()), JdbcJson.write(objectMapper, plan.targetClimateMetrics()), plan.createdBy(), plan.updatedBy(), Timestamp.from(plan.createdAt()), Timestamp.from(plan.updatedAt()));
        }
        jdbc.update("delete from season_plan_target_territories where season_plan_id = ?", plan.id());
        for (String territory : plan.targetTerritories()) {
            jdbc.update("insert into season_plan_target_territories (id, season_plan_id, territory) values (?, ?, ?)", UUID.randomUUID(), plan.id(), territory);
        }
        jdbc.update("delete from season_plan_time_windows where season_plan_id = ?", plan.id());
        for (TimeWindow window : plan.timeWindows()) {
            jdbc.update("insert into season_plan_time_windows (id, season_plan_id, starts_at, ends_at) values (?, ?, ?, ?)", UUID.randomUUID(), plan.id(), Timestamp.valueOf(window.start()), Timestamp.valueOf(window.end()));
        }
        for (ChecklistItem item : plan.readinessChecklist()) {
            jdbc.update("insert into readiness_checklist_items (id, season_plan_id, item_key, complete, completed_by, completed_at)\nvalues (?, ?, ?, ?, ?, ?)\non conflict (season_plan_id, item_key) do update\n   set complete = excluded.complete,\n       completed_by = case\n           when readiness_checklist_items.complete then readiness_checklist_items.completed_by\n           when excluded.complete then excluded.completed_by\n           else null\n       end,\n       completed_at = case\n           when readiness_checklist_items.complete then readiness_checklist_items.completed_at\n           when excluded.complete then excluded.completed_at\n           else null\n       end\n", UUID.randomUUID(), plan.id(), item.key(), item.complete(), item.complete() ? plan.updatedBy() : null, item.complete() ? Timestamp.from(plan.updatedAt()) : null);
        }
        return plan;
    }
    
    @Override
    public Optional<SeasonPlan> findById(UUID id) {
        List<SeasonPlan> plans = jdbc.query("select * from season_plans where id = ?", this::mapPlan, id);
        if (plans.isEmpty()) {
            return Optional.empty();
        }
        SeasonPlan plan = plans.get(0);
        plan.setTargetTerritories(jdbc.queryForList("select territory from season_plan_target_territories where season_plan_id = ? order by territory", String.class, id));
        plan.setTimeWindows(jdbc.query("select starts_at, ends_at from season_plan_time_windows where season_plan_id = ? order by starts_at", (rs,rowNum)->new TimeWindow(toLocalDateTime(rs, "starts_at"), toLocalDateTime(rs, "ends_at")), id));
        plan.setReadinessChecklist(jdbc.query("select item_key, complete from readiness_checklist_items where season_plan_id = ? order by item_key", (rs,rowNum)->new ChecklistItem(rs.getString("item_key"), rs.getBoolean("complete")), id));
        return Optional.of(plan);
    }
    
