    }
    
    @Override
    public UserDetails loadUserByUsername(String username) {
        String normalized;
        try {
            normalized = UsernameNormalizer.normalize(username);
        } catch (IllegalArgumentException error) {
            throw new UsernameNotFoundException("invalid credentials");
        }
        return jdbc.query("select u.id, u.username, u.display_name, u.enabled, u.system_admin, c.password_hash\n  from users u join local_credentials c on c.user_id = u.id\n where u.username = ?\n", (rs)->{
            if (!rs.next()) throw new UsernameNotFoundException("invalid credentials");
            UUID id = rs.getObject("id", UUID.class);
            LinkedHashSet<ActorRole> roles = new LinkedHashSet<>(jdbc.query("select role from user_roles where user_id = ?", (rolesRs,row)->ActorRole.valueOf(rolesRs.getString(1)), id));
            return new LocalUserDetails(id, rs.getString("username"), rs.getString("display_name"), rs.getString("password_hash"), rs.getBoolean("enabled"), rs.getBoolean("system_admin"), roles);
        }, normalized);
    }
