    private final Set<ActorRole> roles;
    
    public LocalUserDetails(UUID userId, String username, String displayName, String password, boolean enabled, Set<ActorRole> roles) {
        this(userId, username, displayName, password, enabled, false, roles);
    }
    
    @Override
