        java.util.List<GrantedAuthority> authorities = new java.util.ArrayList<>(roles.stream().map((role)->new SimpleGrantedAuthority("ROLE_" + role.name())).toList());
        if (systemAdministrator) authorities.add(new SimpleGrantedAuthority("ROLE_SYSTEM_ADMIN"));
        return authorities;
    }
    
    @Override
