class UserAdministrationException extends RuntimeException {
    
    enum Kind {
        /*public static final*/ VALIDATION /* = new Kind() */ /*enum*/ ,
        /*public static final*/ DUPLICATE_USERNAME /* = new Kind() */ /*enum*/ ,
        /*public static final*/ INVALID_CURRENT_PASSWORD /* = new Kind() */ /*enum*/ ;
    }
    private final Kind kind;
    
    UserAdministrationException(Kind kind, String message) {
        super(message);
        this.kind = kind;
    }
    
    Kind kind() {
        return kind;
    }
}

enum Kind {
    /*public static final*/ VALIDATION /* = new Kind() */ /*enum*/ ,
