}

@RestControllerAdvice
class UserAdministrationExceptionHandler {
    
    @ExceptionHandler(UserAdministrationException.class)
    ResponseEntity<Map<String, String>> handle(UserAdministrationException error) {
        HttpStatus status = switch (error.kind()) {
        case VALIDATION -> yield HttpStatus.BAD_REQUEST;
        case DUPLICATE_USERNAME -> yield HttpStatus.CONFLICT;
        case INVALID_CURRENT_PASSWORD -> yield HttpStatus.BAD_REQUEST;
        };
        String code = switch (error.kind()) {
        case VALIDATION -> yield "VALIDATION_FAILED";
        case DUPLICATE_USERNAME -> yield "USERNAME_CONFLICT";
        case INVALID_CURRENT_PASSWORD -> yield "INVALID_CURRENT_PASSWORD";
        };
        return ResponseEntity.status(status).body(Map.of("code", code, "message", error.getMessage()));
    }
}

public final class UsernameNormalizer {
    private static final Pattern VALID = Pattern.compile("[a-z0-9][a-z0-9._-]{0,99}");
    
    private UsernameNormalizer() {
    }
    
    public static String normalize(String username) {
        String normalized = username == null ? "" : username.trim().toLowerCase(Locale.ROOT);
        if (!VALID.matcher(normalized).matches()) throw new IllegalArgumentException("invalid username");
        return normalized;
    }
}

